```javascript
// app/maintenance/addTask.tsx
import React, { useState, useContext } from 'react';
import { View, Text, TextInput, Button, StyleSheet, Alert } from 'react-native';
import { DataContext } from '../../contexts/DataContext';
import { useTheme } from '@react-navigation/native';
import { router } from 'expo-router';

const AddMaintenanceTask = () => {
  const theme = useTheme();
  const { saveData } = useContext(DataContext);
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [dueDate, setDueDate] = useState(''); // Consider using a date picker
  const [assignedCrew, setAssignedCrew] = useState('');

  const handleSubmit = () => {
    // Basic validation
    if (!title || !description || !dueDate || !assignedCrew) {
      Alert.alert('Error', 'Please fill in all fields.');
      return;
    }

    // Create new task object
    const newTask = {
      id: Date.now().toString(), // Generate a unique ID
      title,
      description,
      dueDate,
      assignedCrew,
      status: 'Open', // Default status
    };

    // Save the new task (assuming DataContext handles adding to the existing data)
    saveData((prevData) => ({
      ...prevData,
      maintenanceTasks: [...prevData.maintenanceTasks, newTask],
    }));

    // Navigate back
    router.back();
  };

  return (
    <View style={[styles.container, { backgroundColor: theme.colors.background }]}>
      <Text style={[styles.title, { color: theme.colors.text }]}>Add Maintenance Task</Text>

      <TextInput
        style={[styles.input, { backgroundColor: theme.colors.card, color: theme.colors.text }]}
        placeholder="Title"
        placeholderTextColor={theme.dark ? '#A9A9A9' : '#808080'}
        value={title}
        onChangeText={setTitle}
      />
      <TextInput
        style={[styles.input, { backgroundColor: theme.colors.card, color: theme.colors.text }]}
        placeholder="Description"
        placeholderTextColor={theme.dark ? '#A9A9A9' : '#808080'}
        value={description}
        onChangeText={setDescription}
      />
      <TextInput
        style={[styles.input, { backgroundColor: theme.colors.card, color: theme.colors.text }]}
        placeholder="Due Date"
        placeholderTextColor={theme.dark ? '#A9A9A9' : '#808080'}
        value={dueDate}
        onChangeText={setDueDate}
      />
      <TextInput
        style={[styles.input, { backgroundColor: theme.colors.card, color: theme.colors.text }]}
        placeholder="Assigned Crew"
        placeholderTextColor={theme.dark ? '#A9A9A9' : '#808080'}
        value={assignedCrew}
        onChangeText={setAssignedCrew}
      />

      <Button title="Submit" onPress={handleSubmit} />
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
    padding: 20,
  },
  title: {
    fontSize: 24,
    fontWeight: 'bold',
    marginBottom: 20,
  },
  input: {
    borderWidth: 1,
    borderColor: '#ccc',
    borderRadius: 5,
    padding: 10,
    marginBottom: 10,
  },
});

export default AddMaintenanceTask;
```

